class AuditStore:
    """Append-only in-memory store for migrated audit events."""

    __slots__ = ("__events", "__event_ids")

    def __init__(self) -> None:
        self.__events: tuple[dict, ...] = ()
        self.__event_ids: frozenset[int] = frozenset()

    def append(self, event: dict) -> None:
        """Append a defensive copy of one event."""
        copied_event = dict(event)
        self.__events = self.__events + (copied_event,)
        self.__event_ids = self.__event_ids | {copied_event["evt_id"]}

    def events(self) -> list[dict]:
        """Return defensive copies in append order."""
        return [dict(event) for event in self.__events]

    def __len__(self) -> int:
        return len(self.__events)

    def _contains_evt_id(self, evt_id: int) -> bool:
        return evt_id in self.__event_ids


def migrate_event(row: dict) -> dict:
    """Convert one legacy AUD_EVENT CSV row into its modern event form."""
    timestamp = row["EVT_TS"]

    return {
        "evt_id": int(row["EVT_ID"]),
        "ts": (
            f"{timestamp[0:4]}-{timestamp[4:6]}-{timestamp[6:8]}"
            f"T{timestamp[8:10]}:{timestamp[10:12]}:{timestamp[12:14]}"
        ),
        "code": row["EVT_CD"],
        "user_id": row["USR_ID"],
        "entity": row["ENT_NAME"],
        "entity_id": row["ENT_ID"],
        "old_val": row["OLD_VAL"],
        "new_val": row["NEW_VAL"],
    }


def migrate(rows: list[dict], store: AuditStore | None = None) -> AuditStore:
    """Migrate rows in canonical numeric event order without duplicating event IDs."""
    if store is None:
        store = AuditStore()

    for row in sorted(rows, key=lambda item: int(item["EVT_ID"])):
        evt_id = int(row["EVT_ID"])
        if not store._contains_evt_id(evt_id):
            store.append(migrate_event(row))

    return store
